"""
    Calculates coefficient of variation for single feature

    Parameters
    ----------
    profile_jsons: Profile summary serialized json
    feature_name: Name of feature

    Returns
    -------
    coefficient_of_variation : Calculated coefficient of variation for feature
    """
def __calculate_coefficient_of_variation(
    profile_jsons: Any, feature_name: Any
) -> object {
    feature = profile_jsons.get("columns").get(feature_name);
    coefficient_of_variation = (
        feature.get("numberSummary").get("stddev")
        / feature.get("numberSummary").get("mean")
    )
        if (feature.get("numberSummary") is not None)
        else 0;
    return coefficient_of_variation;
}

"""Formats some number of seconds into a string of format d days, x hours, y minutes, z seconds"""
def format_seconds(time_seconds: Any) -> object {
    seconds = time_seconds;
    hours = 0;
    minutes = 0;
    days = 0;
    while (seconds >= 60) {
        if (seconds >= (60 * 60 * 24)) {
            seconds -= 60 * 60 * 24;
            days += 1;
        } elif (seconds >= (60 * 60)) {
            seconds -= 60 * 60;
            hours += 1;
        } elif (seconds >= 60) {
            seconds -= 60;
            minutes += 1;
        }
    }
    return f"{days}d {hours}h {minutes}m {seconds}s";
}

