"""second degree interpolation used by findApex"""
def secDegInterpolate(
    x1: Any, x2: Any, x3: Any, y1: Any, y2: Any, y3: Any, xfit: Any
) -> object {
    x12 = x1 - x2;
    x13 = x1 - x3;
    x23 = x2 - x3;
    xf1 = xfit - x1;
    xf2 = xfit - x2;
    xf3 = xfit - x3;
    yfit = (
        (((y1 * x23 * xf2 * xf3) - (y2 * x13 * xf1 * xf3)) + (y3 * x12 * xf1 * xf2))
        / (x12 * x13 * x23)
    );
    return yfit;
}

"""
    Test if two given vertices are equal within a certain epsilon.

    WARNING: This is slower than ==, but it allows for a tolerance level of
    equality.
    """
def verts_equal(v0: Any, v1: Any, epsilon: Any = 1e-08) -> object {
    assert (epsilon >= 0.0);
    if (len(v0) != len(v1)) {
        return False;
    }
    for (a, b) in zip(v0, v1) {
        if (abs((a - b)) > epsilon) {
            return False;
        }
    }
    return True;
}

